<?php require_once __DIR__.'/../includes/functions.php'; require_login(['admin']); verify_csrf(); $pdo=db(); if(isset($_POST['add'])){$pdo->prepare('INSERT INTO remittance_companies (name,description,active) VALUES (?,?,1)')->execute([trim($_POST['name']),trim($_POST['description'])]);flash('ok','تمت الإضافة');header('Location: companies.php');exit;} if(isset($_POST['upd'])){$pdo->prepare('UPDATE remittance_companies SET name=?,description=?,active=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['description']),(int)$_POST['active'],(int)$_POST['id']]);flash('ok','تم التعديل');header('Location: companies.php');exit;} $rows=$pdo->query('SELECT * FROM remittance_companies ORDER BY id DESC')->fetchAll();$title='الشركات';include __DIR__.'/../includes/header.php'; ?><div class='card p-3'><a href='dashboard.php' class='btn btn-sm btn-outline-secondary mb-2'>رجوع</a><form method='post' class='row g-2 mb-2'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><div class='col'><input class='form-control' name='name' required></div><div class='col'><input class='form-control' name='description'></div><div class='col'><button class='btn btn-dark w-100' name='add' value='1'>إضافة</button></div></form><table class='table table-bordered table-sm'><tr><th>ID</th><th>Name</th><th>Description</th><th>Active</th><th></th></tr><?php foreach($rows as $r): ?><tr><form method='post'><input type='hidden' name='<?= e($config['security']['csrf_key']) ?>' value='<?= e(csrf_token()) ?>'><input type='hidden' name='id' value='<?= $r['id'] ?>'><td><?= $r['id'] ?></td><td><input name='name' value='<?= e($r['name']) ?>'></td><td><input name='description' value='<?= e($r['description']) ?>'></td><td><select name='active'><option value='1' <?= $r['active']?'selected':'' ?>>1</option><option value='0' <?= !$r['active']?'selected':'' ?>>0</option></select></td><td><button class='btn btn-sm btn-primary' name='upd' value='1'>حفظ</button></td></form></tr><?php endforeach; ?></table></div><?php include __DIR__.'/../includes/footer.php';
